$AlertsFile = ".\perimeter_deception_engine\deception_alerts.json"; if (Test-Path $AlertsFile) { $Data = Get-Content $AlertsFile | ConvertFrom-Json; Write-Output "=================================================="; Write-Output "     ADF-OS ENTERPRISE SOC - PERIMETER MONITOR     "; Write-Output "=================================================="; Write-Output "Alertas Activas Detectadas: $($Data.Count)"; Write-Output "--------------------------------------------------"; foreach ($Alert in $Data) { Write-Output "[!] [$($Alert.Timestamp)] TIPO: $($Alert.IncidentType) -> DESTINO: $($Alert.TargetEndpoint)" }; Write-Output "==================================================" } else { Write-Output "[-] No se encontro base de datos de alertas." }
